import json
from itertools import permutations

def solve():
    # Define puzzle attributes
    houses = [1, 2, 3, 4, 5]

    names = ['Peter', 'Alice', 'Eric', 'Bob', 'Arnold']
    months = ['april', 'feb', 'mar', 'jan', 'sept']
    cigars = ['pall mall', 'prince', 'dunhill', 'blends', 'blue master']
    drinks = ['water', 'coffee', 'tea', 'milk', 'root beer']

    solutions = []

    # Iterate over all possible permutations while enforcing constraints incrementally
    for names_perm in permutations(names):
        # Constraint 13: Eric is in the third house.
        if names_perm[2] != 'Eric':
            continue

        pos_name = {names_perm[i]: i + 1 for i in range(5)}

        # Constraint 1 and 5: Root beer lover is Eric, and Peter is somewhere to the right of Eric.
        # Since Eric is the root beer lover, this reduces to Peter is to the right of Eric.
        if not (pos_name['Peter'] > pos_name['Eric']):
            continue

        # Constraint 9: Arnold is directly left of Peter.
        if not (pos_name['Arnold'] + 1 == pos_name['Peter']):
            continue

        # Months permutations with constraints
        for months_perm in permutations(months):
            pos_month = {months_perm[i]: i + 1 for i in range(5)}

            # Constraint 8: February is in the second house.
            if months_perm[1] != 'feb':
                continue

            # Constraint 6: One house between January and Peter.
            if abs(pos_month['jan'] - pos_name['Peter']) != 2:
                continue

            # Constraint 3: April is Bob's birthday.
            if pos_month['april'] != pos_name['Bob']:
                continue

            # Cigars permutations with constraints
            for cigars_perm in permutations(cigars):
                pos_cigar = {cigars_perm[i]: i + 1 for i in range(5)}

                # Constraint 2: Pall Mall is in the third house.
                if cigars_perm[2] != 'pall mall':
                    continue

                # Constraint 7: Blends smoker has February birthday -> blends in house 2 (since Feb is house 2).
                if cigars_perm[1] != 'blends':
                    continue

                # Constraint 4: Dunhill smoker is the person whose birthday is in March.
                if pos_cigar['dunhill'] != pos_month['mar']:
                    continue

                # Drinks permutations with constraints
                for drinks_perm in permutations(drinks):
                    pos_drink = {drinks_perm[i]: i + 1 for i in range(5)}

                    # Constraint 1: Root beer lover is Eric.
                    if drinks_perm[pos_name['Eric'] - 1] != 'root beer':
                        continue

                    # Constraint 10: Milk is not in the fifth house.
                    if drinks_perm[4] == 'milk':
                        continue

                    # Constraint 11: Blue Master smoker is the coffee drinker.
                    if pos_cigar['blue master'] != pos_drink['coffee']:
                        continue

                    # Constraint 12: One house between tea drinker and coffee drinker.
                    if abs(pos_drink['tea'] - pos_drink['coffee']) != 2:
                        continue

                    # All constraints satisfied; record solution
                    solution_rows = []
                    for i in range(5):
                        solution_rows.append([
                            str(i + 1),
                            names_perm[i],
                            months_perm[i],
                            cigars_perm[i],
                            drinks_perm[i]
                        ])
                    solutions.append(solution_rows)

    # Prepare JSON output
    header = ["House", "Name", "birthday month", "favorite cigar", "favorite drink"]

    if not solutions:
        output = {
            "solution": {
                "header": header,
                "rows": []
            }
        }
    else:
        # Use the first solution (should be unique)
        output = {
            "solution": {
                "header": header,
                "rows": solutions[0]
            }
        }

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    solve()
